def extract(t, start):
    # from 'def name(' walk lines while indented or blank
    i=start
    lines=[t[i:t.find('\n',i)+1]]
    p=t.find('\n',i)+1
    while p<len(t):
        e=t.find('\n',p)
        line=t[p:e+1 if e>=0 else len(t)]
        if line.strip()=='' :
            lines.append(line); p=e+1; continue
        if line.startswith('    ') or line.startswith('\t'):
            lines.append(line); p=e+1
        else: break
    return ''.join(lines)

